using System.Data.Common;
using LibraryManagement.Models;
using Microsoft.Data.Sqlite;

namespace LibraryManagement.Data;

/// <summary>
/// Creates the database connection used by the Dapper repositories.
/// </summary>
public interface IDbConnectionFactory
{
    DbConnection CreateConnection();

    /// <summary>
    /// Query that returns the identity value generated by the last INSERT
    /// on the same connection.
    /// </summary>
    string LastInsertIdQuery { get; }
}

public sealed class SqliteConnectionFactory : IDbConnectionFactory
{
    private readonly string _connectionString;

    public SqliteConnectionFactory(string connectionString)
    {
        _connectionString = connectionString;
    }

    public DbConnection CreateConnection()
        => new SqliteConnection(_connectionString);

    public string LastInsertIdQuery
        => "SELECT last_insert_rowid()";
}

/// <summary>
/// Replaces what the EF DbContext did for the repositories: one connection
/// per request, a queue of pending Add/Update/Delete commands that
/// SaveChangesAsync runs in a single transaction, and a small identity map
/// so the same Book / User row loaded twice in a request is one object
/// (as EF change tracking guaranteed).
/// </summary>
public interface IDapperUnitOfWork
{
    string LastInsertIdQuery { get; }

    Task<DbConnection> GetConnectionAsync();

    void Enqueue(Func<DbConnection, DbTransaction, Task> command);

    Task SaveChangesAsync();

    /// <summary>Runs <paramref name="work"/> in its own transaction, immediately.</summary>
    Task ExecuteInTransactionAsync(
        Func<DbConnection, DbTransaction, Task> work);

    Book Track(Book book);

    User Track(User user);

    Book? FindTrackedBook(int bookId);

    User? FindTrackedUser(int userId);
}

public sealed class DapperUnitOfWork : IDapperUnitOfWork, IDisposable
{
    private readonly IDbConnectionFactory _factory;
    private readonly List<Func<DbConnection, DbTransaction, Task>> _pending = new();
    private readonly Dictionary<int, Book> _books = new();
    private readonly Dictionary<int, User> _users = new();
    private DbConnection? _connection;

    public DapperUnitOfWork(IDbConnectionFactory factory)
    {
        _factory = factory;
    }

    public string LastInsertIdQuery => _factory.LastInsertIdQuery;

    public async Task<DbConnection> GetConnectionAsync()
    {
        if (_connection == null)
        {
            var connection = _factory.CreateConnection();
            await connection.OpenAsync();
            _connection = connection;
        }

        return _connection;
    }

    public void Enqueue(Func<DbConnection, DbTransaction, Task> command)
        => _pending.Add(command);

    public async Task SaveChangesAsync()
    {
        if (_pending.Count == 0)
        {
            return;
        }

        var commands = _pending.ToArray();
        _pending.Clear();

        await ExecuteInTransactionAsync(async (connection, tx) =>
        {
            foreach (var command in commands)
            {
                await command(connection, tx);
            }
        });
    }

    public async Task ExecuteInTransactionAsync(
        Func<DbConnection, DbTransaction, Task> work)
    {
        var connection = await GetConnectionAsync();
        await using var tx = await connection.BeginTransactionAsync();

        try
        {
            await work(connection, tx);
            await tx.CommitAsync();
        }
        catch (DbException)
        {
            await tx.RollbackAsync();

            throw;
        }
    }

    public Book Track(Book book)
        => _books.TryGetValue(book.BookId, out var existing)
            ? existing
            : _books[book.BookId] = book;

    public User Track(User user)
        => _users.TryGetValue(user.UserId, out var existing)
            ? existing
            : _users[user.UserId] = user;

    public Book? FindTrackedBook(int bookId)
        => _books.GetValueOrDefault(bookId);

    public User? FindTrackedUser(int userId)
        => _users.GetValueOrDefault(userId);

    public void Dispose()
    {
        _connection?.Dispose();
    }
}
